from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        if max(nums) < 0:
            return max(nums)

        cur = best = nums[0]
        has_negative = nums[0] < 0

        for i in range(1, len(nums)):
            a = nums[i]
            has_negative |= a < 0
            cur = max(a, cur + a)
            best = max(best, cur)

        if not has_negative:
            return best

        prefix = 0
        gain = {}
        floor = 0
        max_gain = 0
        best_deleted = -(10 ** 30)

        for a in nums:
            prefix += a

            if a < 0:
                gain[a] = max(gain.get(a, 0), floor) - a
                max_gain = max(max_gain, gain[a])

            best_deleted = max(best_deleted, prefix + max_gain)

            floor = max(floor, -prefix)
            max_gain = max(max_gain, floor)

        return max(best, best_deleted)
